"""Real Metal browser, direct-file/offline walk and bundle mutation checks."""
import argparse, json, pathlib, re, tempfile, time
from playwright.sync_api import sync_playwright
parser=argparse.ArgumentParser();parser.add_argument('site');parser.add_argument('--shots');args=parser.parse_args()
site=pathlib.Path(args.site).resolve()
shots=pathlib.Path(args.shots) if args.shots else None
if shots: shots.mkdir(parents=True,exist_ok=True)
def check(condition,label):
    assert condition,label
    print('PASS',label,flush=True)
with sync_playwright() as p:
    browser=p.chromium.launch(headless=True,args=['--use-angle=metal'])
    for width,height,reduced in [(1280,720,False),(390,844,False),(320,568,False),(844,390,False),(390,844,True)]:
        context=browser.new_context(viewport={'width':width,'height':height},reduced_motion='reduce' if reduced else 'no-preference',offline=True)
        page=context.new_page();errors=[];remote=[]
        page.on('pageerror',lambda error:errors.append(str(error)))
        page.on('request',lambda req:remote.append(req.url) if req.url.startswith(('http:','https:')) else None)
        started=time.monotonic();page.goto(site.as_uri()+'/index.html');page.wait_for_function('window.insiyab && insiyab.deck.isInitialized')
        check(time.monotonic()-started<3,f'{width}: usable within three seconds from folder, network off')
        renderer=page.evaluate("""()=>{const gl=document.querySelector('canvas').getContext('webgl2'),ext=gl.getExtension('WEBGL_debug_renderer_info');return ext?gl.getParameter(ext.UNMASKED_RENDERER_WEBGL):gl.getParameter(gl.RENDERER)}""")
        check('Metal' in renderer and 'SwiftShader' not in renderer,'real graphics chip: '+renderer)
        check(page.locator('#fixture').is_visible(),f'{width}: stand-in label visible')
        check(page.locator('#map-failure').is_hidden(),f'{width}: map rendered')
        check(page.evaluate("Math.abs(insiyab.time-(INSIYAB_BUNDLE['metrics.json'].targets.find(t=>t.level==='route'&&t.target==='boardings').split.origins[0]))<120"),f'{width}: opens at untouched evaluation hours')
        first=page.evaluate('insiyab.time');page.wait_for_timeout(250);second=page.evaluate('insiyab.time')
        check(second==first if reduced else second>first,f'{width}: reduced motion respected' if reduced else f'{width}: clock and buses moving')
        page.evaluate('insiyab.setTime(insiyab.model.meta.origins[0]+3600)')
        page.wait_for_timeout(150)
        check(page.evaluate('insiyab.buses.length>0'),f'{width}: buses exist at record time')
        evaluation=page.locator('#evaluation').inner_text()
        check(page.evaluate("()=>{const t=INSIYAB_BUNDLE['metrics.json'].targets.find(t=>t.level==='route'&&t.target==='boardings'),r=t.pooled.find(r=>r.model===t.chosen);return document.querySelector('#evaluation strong').textContent===new Intl.NumberFormat('en-GB',{maximumFractionDigits:2}).format(r.mae)}"),f'{width}: fixed evaluation uses the chosen pooled result')
        # Find a moving trip and independently check the rendered position on its path.
        check(page.evaluate("""()=>{const m=insiyab.model,t=m.trips.find(t=>t.visits.length>1),a=t.visits[0],b=t.visits[1],time=(a.act_dep+b.act_arr)/2;insiyab.setTime(time);const bus=insiyab.deck.props.layers.find(l=>l.id==='buses').props.data.find(b=>b.trip_id===t.trip_id);const expected=(a.distance+b.distance)/2;return Math.abs(bus.distance-expected)<.0001;}"""),f'{width}: bus at the correct distance between recorded stops')
        check(page.locator('#evaluation').inner_text()==evaluation,f'{width}: replay does not alter fixed evaluation')
        page.evaluate('insiyab.setTime(insiyab.model.meta.origins[0]+3600)')
        fill=page.evaluate("""()=>{const p=insiyab.model.paths.flatMap(p=>p.points),f=insiyab.fit,r=document.querySelector('#map').getBoundingClientRect();return Math.max((Math.max(...p.map(p=>p[0]))-Math.min(...p.map(p=>p[0])))*f.scale/r.width,(Math.max(...p.map(p=>p[1]))-Math.min(...p.map(p=>p[1])))*f.scale/r.height)}""")
        check(fill>=.84,f'{width}: network fills {fill:.0%} of map')
        check(page.evaluate('document.documentElement.scrollWidth<=innerWidth'),f'{width}: no horizontal overflow')
        sizes=page.locator('button,select,input[type=range]').evaluate_all('(els)=>els.filter(e=>e.getBoundingClientRect().width>0).map(e=>({id:e.id,height:e.getBoundingClientRect().height}))')
        check(all(e['height']>=44 for e in sizes),f'{width}: all controls at least 44px {sizes}')
        if width==390:check(page.locator('#time').bounding_box()['width']>=width-40,f'{width}: full-width time slider')
        if width in [1280,390] and not reduced:
            rect=page.locator('#play').bounding_box();check(rect['y']+rect['height']<=height,f'{width}: clock control visible without scrolling')
            if shots:
                page.evaluate("insiyab.setTime(INSIYAB_BUNDLE['metrics.json'].targets.find(t=>t.level==='route'&&t.target==='boardings').split.origins[0])");page.screenshot(path=str(shots/f'first-{width}x{height}.png'))
        page.locator('[data-route]').nth(1).click()
        check(page.evaluate('new Set(insiyab.buses.map(b=>b.route_id)).size<=1'),f'{width}: focus filters buses to one route')
        page.locator('[data-route]').first.click()
        check(page.evaluate("insiyab.deck.props.layers.find(l=>l.id==='communities').props.data.length===0"),f'{width}: overview has no overlapping community labels')
        page.locator('#entity-type').select_option('bus');check('model year' in page.locator('#detail').inner_text(),f'{width}: bus details')
        page.locator('#entity-type').select_option('community');check('boardings over the service day' in page.locator('#detail').inner_text(),f'{width}: community totals')
        page.locator('[data-view="forecast"]').click()
        check(page.locator('#forecast-controls').is_visible(),f'{width}: forecast switch responds')
        page.wait_for_function("!!INSIYAB_BUNDLE['forecast/boardings-stop.json']")
        check(page.locator('#challenge svg').count()==1,f'{width}: forecast has a time-series chart')
        page.locator('#freeze').click()
        origin=page.evaluate('insiyab.forecastOrigin')
        page.evaluate('insiyab.setTime(insiyab.forecastOrigin)')
        check(page.evaluate("insiyab.deck.props.layers.find(l=>l.id==='actual-halos').props.data.length===0"),f'{width}: no actuals revealed ahead of clock')
        page.evaluate('insiyab.setTime(insiyab.forecastOrigin+3600)')
        check(page.evaluate("insiyab.deck.props.layers.find(l=>l.id==='actual-halos').props.data.length>0"),f'{width}: reality fills forecast after clock passes bin')
        check('naive forecast' in page.locator('#error-counter').inner_text(),f'{width}: rolling error against naive visible')
        check(page.locator('[data-actual]').inner_text()=='?',f'{width}: challenge hides actual')
        started=time.monotonic();page.locator('#reveal').click()
        check(page.locator('[data-actual]').inner_text()!='?' and time.monotonic()-started<2,f'{width}: one tap reveals actual in under two seconds')
        if shots and width in [1280,390] and not reduced:
            page.evaluate('window.scrollTo(0,0)');page.screenshot(path=str(shots/f'forecast-{width}x{height}.png'))
        check('miss' in page.locator('[data-miss]').inner_text().lower(),f'{width}: miss and naive comparison shown')
        page.locator('#forecast-time').select_option(index=1)
        check(page.locator('[data-actual]').inner_text()=='?',f'{width}: new time hides the answer again')
        missing=page.evaluate("insiyab.model.network.stops.find(s=>!INSIYAB_BUNDLE['forecast/boardings-stop.json'].series.some(f=>f.id===s.stop_id))?.stop_id")
        if missing:
            page.locator('#forecast-stop').select_option(missing)
            check('No held-out afternoon forecast supplied' in page.locator('#challenge').inner_text(),f'{width}: missing stop forecast is explicit')
        page.locator('[data-view="model"]').click()
        check('naive forecast' in page.locator('#model-sentence').inner_text(),f'{width}: model sentence from bundle')
        check(page.locator('#subset-chart svg').count()==1,f'{width}: subset comparison chart exists')
        check(page.locator('#model-chart svg').count()==1,f'{width}: model comparison chart across horizons')
        check(page.evaluate('document.documentElement.scrollWidth<=innerWidth'),f'{width}: model page has no sideways overflow')
        if shots and width in [1280,390] and not reduced:page.screenshot(path=str(shots/f'model-{width}x{height}.png'))
        page.locator('#model-horizon').select_option(index=0)
        expected=page.evaluate("()=>{const t=INSIYAB_BUNDLE['metrics.json'].targets[+document.querySelector('#model-target').value],h=+document.querySelector('#model-horizon').value,ids=t.models.filter(m=>m.is_baseline).map(m=>m.model);return new Intl.NumberFormat('en-GB',{maximumFractionDigits:2}).format(Math.min(...t.results.filter(r=>ids.includes(r.model)&&r.horizon===h&&r.subset==='all').map(r=>r.mae)));}")
        check(f'Best naive forecast in this table: {expected}.' in page.locator('#model-sentence').inner_text(),f'{width}: headline uses strongest naive at selected horizon')
        page.locator('#model summary').filter(has_text='How these errors are counted').click()
        check('MAPE' in page.locator('#mape-rule').inner_text(),f'{width}: MAPE denominator rule visible')
        targets=page.evaluate("INSIYAB_BUNDLE['metrics.json'].targets")
        for ti,target in enumerate(targets):
            page.locator('#model-target').select_option(str(ti))
            if target.get('tested_on'):check(target['tested_on'] in page.locator('#model .forecast-limit').inner_text(),f'{width}: exact target testing limitation shown')
            if target['target']=='arrival_delay_seconds':check('stops ahead' in page.locator('#model-chart').text_content() and 'seconds' in page.locator('#model-numbers').inner_text(),f'{width}: delay uses stops and seconds')
            chosen=target.get('chosen');pool=next((r for r in target.get('pooled',[]) if r['model']==chosen),None)
            if pool and pool.get('skill_lo',1)<=0<=pool.get('skill_hi',-1):check('includes zero' in page.locator('#model-reliability').inner_text(),f'{width}: uncertain gain is explicit')
        page.locator('[data-view="gap"]').click()
        check(page.locator('#gap-routes svg').count()==1,f'{width}: route-hour gap comparison chart')
        before=page.locator('[data-total="passenger_minutes_over_seats"]').inner_text()
        check(page.locator('#close-gaps').inner_text()=='Close the gaps',f'{width}: gap starts before changes')
        check('simulated' in page.locator('#gap-totals').inner_text().lower(),f'{width}: gap totals explicitly simulated')
        page.locator('#close-gaps').click()
        after=page.locator('[data-total="passenger_minutes_over_seats"]').inner_text()
        expected=page.evaluate("new Intl.NumberFormat('en-GB',{maximumFractionDigits:2}).format(INSIYAB_BUNDLE['gap.json'].totals.after.passenger_minutes_over_seats)")
        check(after==expected and before!=after,f'{width}: close gaps uses bundle after totals')
        check(page.locator('.decision').count()==page.evaluate("INSIYAB_BUNDLE['decisions.json'].decisions.length"),f'{width}: every decision is shown')
        check(page.locator('.effects').first.inner_text().lower().startswith('simulated'),f'{width}: each effect labelled simulated')
        if shots and width in [1280,390] and not reduced:page.screenshot(path=str(shots/f'gap-{width}x{height}.png'))
        page.locator('#playback').click()
        check('Played back, nobody is connected' in page.locator('#room-count').inner_text(),f'{width}: disconnected playback is labelled')
        check(page.locator('.decision-state').first.inner_text()=='Proposed',f'{width}: no invented depot confirmation')
        page.evaluate('()=>{window.print=()=>{window.printCalled=true}}')
        page.locator('[data-print]').first.click()
        page.wait_for_function('window.printCalled===true')
        check(page.evaluate('window.printCalled===true'),f'{width}: print command reached')
        swaps=page.evaluate("INSIYAB_BUNDLE['decisions.json'].decisions[0].swaps??[]")
        for swap in swaps:
            for side in ['from','to']:
                check(swap[side]['trip_id'] in page.locator('#print-order').text_content(),f'{width}: printed swap includes exact {side} trip')
        check('SIMULATION. NOTHING WAS SENT.' in page.locator('#print-order').text_content(),f'{width}: print order carries simulation warning')
        page.emulate_media(media='print')
        check(page.locator('#print-order').is_visible() and page.locator('main').is_hidden(),f'{width}: print exposes only the order')
        pdf=page.pdf(format='A4',prefer_css_page_size=True)
        check(len(re.findall(rb'/Type /Page\b',pdf))==1,f'{width}: order renders as exactly one A4 page')
        check(page.locator('#print-order img').evaluate('(e)=>e.complete && e.naturalWidth>0'),f'{width}: printed decision QR is local and loaded')
        page.emulate_media(media='screen');page.evaluate("dispatchEvent(new Event('afterprint'))")
        page.locator('[data-view="stories"]').click()
        people=page.evaluate("INSIYAB_BUNDLE['personas.json'].personas")
        for i,person in enumerate(people):
            page.locator(f'[data-person="{i}"]').click()
            check(page.locator('#story-say').inner_text()==person['steps'][0]['say'],f"{width}: {person['id']} sentence comes from bundle")
            check('Fictional' in page.locator('#fictional').inner_text(),f"{width}: {person['id']} fiction label")
            check('measured' in page.locator('#story-kind').inner_text().lower(),f"{width}: {person['id']} starts measured")
            check(person['title'] in page.locator('#scene-title').text_content(),f"{width}: {person['id']} figure is named")
            page.evaluate("async()=>{for(const el of document.querySelectorAll('#scene image')){const image=new Image();image.src=el.getAttribute('href');await image.decode();}}")
            check(page.locator('#scene image').count()==1,f"{width}: {person['id']} local Blender render decoded offline")
            check(page.locator('#scene svg').is_visible(),f"{width}: {person['id']} scene exists")
            check(page.locator('#fixture').bounding_box()['y']>=0,f"{width}: {person['id']} stand-in label in viewport")
            check(page.evaluate('document.documentElement.scrollWidth<=innerWidth'),f"{width}: {person['id']} no sideways scroll")
            if shots and width in [1280,390] and not reduced:
                page.screenshot(path=str(shots/f"{person['id']}-{width}x{height}.png"))
            before=person['steps'][0]['before']
            if 'load' in before and 'seats' in before and max(before['load'],before['seats'])<=220:
                check(page.locator('[data-seat]').count()==before['seats'],f"{width}: {person['id']} seat squares equal supplied seats")
                check(page.locator('[data-excess]').count()==max(0,before['load']-before['seats']),f"{width}: {person['id']} excess triangles equal supplied shortfall")
            before_story=page.locator('#scene').inner_html();page.wait_for_timeout(100)
            check(page.locator('#scene').inner_html()==before_story,f"{width}: {person['id']} never advances by timer")
            if len(person['steps'])>1:
                page.locator('#story-next').click()
                check('simulated' in page.locator('#story-kind').inner_text().lower(),f"{width}: {person['id']} change labelled simulated")
                check(page.locator('#story-say').inner_text()==person['steps'][1]['say'],f"{width}: {person['id']} next step from bundle")
                check(page.locator('#scene').inner_html()!=before_story,f"{width}: {person['id']} scene changes on tap")
                check(page.locator('#story-decision > details > summary').count()==1,f"{width}: {person['id']} links its decision")
                original_kind=page.locator('#story-kind').inner_text()
                page.locator('#story-kind').evaluate("e=>e.textContent='Measured'")
                try:assert 'simulated' in page.locator('#story-kind').inner_text().lower()
                except AssertionError:print('PASS negative control rejects an unlabelled simulated story')
                else:raise AssertionError('Simulation label test cannot fail')
                page.locator('#story-kind').evaluate('(e,text)=>e.textContent=text',original_kind)
                if person['steps'][1]['scene']=='phone':
                    check(page.locator('#story-action a').get_attribute('href')=='khutwa/',f'{width}: office worker uses lane 3 phone page')
        page.locator('#story-next').click()
        check(page.locator('#replay').is_visible(),f'{width}: last point of view returns to replay')
        # Negative control: the very same label assertion must reject a deleted label.
        page.locator('#fixture').evaluate('(e)=>e.hidden=true')
        try: assert page.locator('#fixture').is_visible()
        except AssertionError:print('PASS negative control rejects missing stand-in label')
        else:raise AssertionError('Label test cannot fail')
        check(not errors,f'{width}: no page errors {errors}')
        check(not remote,f'{width}: no runtime network requests {remote}')
        context.close()
    # A different bundle is embedded without changing app.js, proving the screen reads it.
    text=(site/'bundle.js').read_text();data=json.loads(text.removeprefix('window.INSIYAB_BUNDLE=').rstrip(';\n'))
    old=data['summary.json']['headline'][0]['value'];data['summary.json']['headline'][0]['value']=old+987
    for v in data.values():v['fixture']=False
    import shutil
    with tempfile.TemporaryDirectory(prefix='insiyab-mutant-') as tmp:
        mutant=pathlib.Path(tmp);shutil.copytree(site,mutant,dirs_exist_ok=True)
        (mutant/'bundle.js').write_text('window.INSIYAB_BUNDLE='+json.dumps(data)+';')
        stop_data=json.loads((site/'data/forecast/boardings-stop.json').read_text());stop_data['fixture']=False
        (mutant/'stop-forecast.js').write_text("window.INSIYAB_BUNDLE['forecast/boardings-stop.json']="+json.dumps(stop_data)+';')
        context=browser.new_context(offline=True);page=context.new_page();page.goto(mutant.as_uri()+'/index.html');page.wait_for_function('window.insiyab && insiyab.deck.isInitialized')
        page.locator('.day-summary summary').click()
        check(page.locator('[data-headline]').inner_text().replace(',','')==str(old+987),'mutated bundle count changes the screen')
        check(page.locator('#fixture').is_hidden(),'fixture false removes stand-in label')
        for name in ['forecast','model','gap','stories']:
            page.locator(f'[data-view="{name}"]').click()
            check(page.locator('#fixture').is_hidden(),f'fixture false removes label on {name}')
        try:assert page.locator('[data-headline]').inner_text().replace(',','')==str(old)
        except AssertionError:print('PASS negative control rejects stale hard-coded bundle count')
        else:raise AssertionError('Bundle test cannot fail')
        context.close()
    browser.close()
print('BROWSER PASS')
